<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {ArrowUpRight,Leaf,Bell,ShieldCheck} from 'lucide-vue-next'
import {api,session,labels,date,type Batch} from '../api'
const batches=ref<Batch[]>([]),notifications=ref<{id:string;message:string;created_at:string}[]>([]),loading=ref(true),error=ref('')
onMounted(async()=>{try{const r=await api<{batches:Batch[];notifications:typeof notifications.value}>('/dashboard');batches.value=r.batches;notifications.value=r.notifications}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
</script>
<template><section class="container page-section"><div class="page-heading split-heading"><div><div class="eyebrow">YOUR COMMUNITY SPACE</div><h1>{{session.user?`${session.user.name}，今天也有好事发生。`:'你的社区工作台'}}</h1><p>从发布到交接，照看每一份食品的旅程。</p></div><RouterLink to="/share" class="button">分享食品<ArrowUpRight :size="17"/></RouterLink></div><div v-if="loading" class="empty-state">正在读取工作台…</div><template v-else-if="error"><div class="empty-state" role="alert"><h3>{{error}}</h3><RouterLink v-if="!session.user" to="/login" class="button">登录工作台</RouterLink><button v-else class="button" @click="$router.go(0)">重新加载</button></div></template><template v-else><div class="org-grid"><div v-for="o in session.organizations" :key="o.id" class="surface org-card"><ShieldCheck :size="25"/><div><h3>{{o.name}}</h3><p>{{labels[o.kind]}}</p></div><span class="status" :class="o.status">{{labels[o.status]}}</span><p v-if="o.status==='pending'" class="org-note">组织审核通过后即可发布或认领食品。请联系试点运营人员完成身份确认。</p></div></div><div class="workspace-layout"><div><h2 class="subheading">我的食品旅程 <span>{{batches.length}}</span></h2><div v-if="!batches.length" class="surface empty-state"><Leaf :size="34"/><h3>从第一份善意开始。</h3><p>这里会显示你发布或认领的食品批次。</p><RouterLink to="/" class="text-button">发现余量 <ArrowUpRight :size="16"/></RouterLink></div><div class="journey-list"><RouterLink v-for="b in batches" :key="b.id" :to="`/batches/${b.id}`" class="surface journey-card"><div class="journey-icon"><Leaf :size="24"/></div><div><small>{{b.is_donor?'我发布的':'我认领的'}} · {{b.area}}</small><h3>{{b.title}}</h3><p>{{b.quantity}} {{labels[b.unit]}} · {{date(b.pickup_end)}} 前领取</p><p v-if="b.recipient_name" class="form-hint">接收组织：{{b.recipient_name}}</p></div><div class="journey-end"><span class="status" :class="b.status">{{labels[b.status]}}</span><ArrowUpRight :size="18"/></div></RouterLink></div></div><aside class="surface notification-panel"><h3><Bell :size="18"/>社区消息</h3><p v-if="!notifications.length" class="muted">暂时没有新消息。认领和交接发生时，通知会出现在这里。</p><article v-for="n in notifications" :key="n.id"><p>{{n.message}}</p><small>{{date(n.created_at)}}</small></article></aside></div></template></section></template>
